"package repository

import (
	"context"
	"time"

	"imc-server/internal/database"
	"imc-server/internal/models"
)

// UserRepository encapsula todas as operações de banco de dados para a entidade Users.
// Seguindo os Design Patterns de padrão ouro, isolamos o SQL da camada de controle (Handlers).
type UserRepository struct{}

// NewUserRepository cria uma nova instância do repositório de usuários.
func NewUserRepository() *UserRepository {
	return &UserRepository{}
}

// GetByEmail busca um usuário ativo no banco através do e-mail corporativo.
// Aplica a função LOWER() para garantir que a busca seja Case-Insensitive (insensível a maiúsculas).
func (r *UserRepository) GetByEmail(ctx context.Context, email string) (*models.User, string, error) {
	// Definimos um timeout de segurança para a query não travar caso o banco fique lento
	queryCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	var user models.User
	var dbPasswordHash string

	// Query traduzida e alinhada com o Schema internacional do PostgreSQL
	query := `
		SELECT id, tenant_id, permission_level_id, name, email, password_hash, is_active 
		FROM users 
		WHERE LOWER(email) = LOWER($1)`

	// Executa a busca no Pool de Conexões do Jackc/PGX
	err := database.Pool.QueryRow(queryCtx, query, email).Scan(
		&user.ID,
		&user.TenantID,
		&user.PermissionLevelID,
		&user.Name,
		&user.Email,
		&dbPasswordHash,
		&user.IsActive,
	)

	if err != nil {
		return nil, "", err // Retorna o erro (ex: pgx.ErrNoRows se não achar)
	}

	return &user, dbPasswordHash, nil
}"

