    function fetchNowPlaying() {
        fetch('/api/player/' + storeId + '/now-playing')
            .then(res => res.json())
            .then(data => {
                if (!data) return;

                const liveBadge = document.getElementById('badge-live-status');
                if (liveBadge) {
                    if (data.online) {
                        liveBadge.className = 'badge bg-success status-pill';
                        liveBadge.innerHTML = '<i class="bi bi-broadcast me-1"></i> AO VIVO';
                    } else {
                        liveBadge.className = 'badge bg-danger status-pill';
                        liveBadge.innerHTML = '<i class="bi bi-x-circle me-1"></i> FORA DO AR';
                    }
                }

                const titleEl = document.getElementById('track-title');
                const artistEl = document.getElementById('track-artist');
                const albumEl = document.getElementById('track-album');
                const typeEl = document.getElementById('track-type');

                if (titleEl && data.title) titleEl.innerText = data.title;
                if (artistEl && data.artist) artistEl.innerText = data.artist;
                if (typeEl && data.media_type) typeEl.innerText = data.media_type;
                if (albumEl) {
                    albumEl.innerText = data.album ? 'Álbum: ' + data.album : '';
                }
            })
            .catch(() => {});
    }"

