"    audioPlayer.volume = 0.8;

    function toggleStreamPlay(forcePlay) {
        if (forcePlay === true && isPlaying) return;

        if (!isPlaying || forcePlay === true) {
            const liveUrl = streamUrl + (streamUrl.includes('?') ? '&' : '?') + 'nocache=' + new Date().getTime();
            audioPlayer.src = liveUrl;
            audioPlayer.play().then(() => {
                isPlaying = true;
                updatePlayUI(true);
            }).catch(err => {
                console.warn("Reprodução automática bloqueada pelo navegador até interação:", err);
                if (forcePlay !== true) {
                    alert("Não foi possível conectar à transmissão da rádio no momento. Verifique se a rádio está online.");
                }
            });
        } else {
            audioPlayer.pause();
            audioPlayer.src = '';
            isPlaying = false;
            updatePlayUI(false);
        }
    }

    // Auto-recuperação de conexão contínua de áudio
    audioPlayer.addEventListener('error', function(e) {
        console.warn("Stream error detectado no player de áudio, tentando reconexão...", e);
        if (isPlaying) {
            setTimeout(reconnectLiveStream, 1500);
        }
    });

    audioPlayer.addEventListener('stalled', function() {
        console.warn("Buffer de áudio estagnado, verificando conexão...");
        if (isPlaying) {
            setTimeout(() => {
                if (audioPlayer.readyState < 2 && isPlaying) {
                    reconnectLiveStream();
                }
            }, 3000);
        }
    });

    function reconnectLiveStream() {
        if (!isPlaying) return;
        const liveUrl = streamUrl + (streamUrl.includes('?') ? '&' : '?') + 'reconnect=' + new Date().getTime();
        audioPlayer.src = liveUrl;
        audioPlayer.load();
        audioPlayer.play().catch(err => console.log("Erro ao reconectar stream:", err));
    }"

