func handleAPITriggerVehicleWarning(w http.ResponseWriter, r *http.Request, cfg *Config) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req TriggerWarningRequest
	err := json.NewDecoder(r.Body).Decode(&req)
	if err != nil {
		http.Error(w, "Invalid JSON body: "+err.Error(), http.StatusBadRequest)
		return
	}

	if req.Plate == "" {
		http.Error(w, "Placa é obrigatória", http.StatusBadRequest)
		return
	}
	if req.VoicePack == "" {
		req.VoicePack = "default"
	}

	displayName, err := TriggerVehicleWarning(cfg, req.Plate, req.VoicePack, req.ChimeFile)
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(map[string]string{"message": err.Error()})
		return
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"status":  "success",
		"message": fmt.Sprintf("Aviso de placa acionado com sucesso: %s", displayName),
	})
}

func handleAPIPreFormattedWarnings(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	warnings, err := ListPreFormattedWarnings()
	if err != nil {
		http.Error(w, "Failed to list pre-formatted warnings: "+err.Error(), http.StatusInternalServerError)
		return
	}
	if warnings == nil {
		warnings = []string{}
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(warnings)
}

