// ListPreFormattedWarnings lists all audio files (.mp3 and .wav) from DB and pre-formatted warning directories.
func ListPreFormattedWarnings() ([]string, error) {
	seen := make(map[string]bool)
	var files []string

	if DB != nil {
		rows, err := DB.Query("SELECT file_name FROM pre_formatted_warnings")
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var fname string
				if rows.Scan(&fname) == nil && fname != "" && !seen[fname] {
					seen[fname] = true
					files = append(files, fname)
				}
			}
		}
	}

	dirsToCheck := []string{"pre_formatted_warnings", "/app/midias/pre_formatted_warnings", "midias/pre_formatted_warnings"}
	for _, dir := range dirsToCheck {
		entries, err := os.ReadDir(dir)
		if err == nil {
			for _, d := range entries {
				if !d.IsDir() {
					name := d.Name()
					ext := strings.ToLower(filepath.Ext(name))
					if (ext == ".mp3" || ext == ".wav") && !seen[name] {
						seen[name] = true
						files = append(files, name)
					}
				}
			}
		}
	}
	return files, nil
}

