				func getRecentLogsJSON(limit int) []LocalLogRecord {
	var list []LocalLogRecord
	if DB == nil {
		return list
	}

	rows, err := DB.Query("SELECT timestamp, level, message FROM local_logs ORDER BY id DESC LIMIT $1", limit)
	if err != nil {
		return list
	}
	defer rows.Close()

	for rows.Next() {
		var r LocalLogRecord
		if errScan := rows.Scan(&r.Timestamp, &r.Level, &r.Message); errScan == nil {
			list = append(list, r)
		}
	}

	// Reverse list to show chronologically
	for i, j := 0, len(list)-1; i < j; i, j = i+1, j-1 {
		list[i], list[j] = list[j], list[i]
	}

	return list
}

