"    // Carregar Logs do Sistema
    function loadSystemLogs() {
        const consoleEl = document.getElementById('system-logs-console');
        if (!consoleEl) return;

        fetch('/api/player/' + storeId + '/diagnostics')
            .then(res => res.json())
            .then(data => {
                if (!data) return;
                consoleEl.innerHTML = '';
                if (Array.isArray(data.recent_logs) && data.recent_logs.length > 0) {
                    data.recent_logs.forEach(l => {
                        const row = document.createElement('div');
                        row.style.marginBottom = '4px';
                        let levelClass = 'log-line-info';
                        const lvl = (l.level || '').toUpperCase();
                        if (lvl.includes('WARN')) levelClass = 'log-line-warn';
                        if (lvl.includes('ERR')) levelClass = 'log-line-err';

                        const safeMsg = (l.message || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
                        row.innerHTML = `<span class="log-line-time">[${l.timestamp || ''}]</span> <span class="${levelClass}">[${lvl}]</span> <span>${safeMsg}</span>`;
                        consoleEl.appendChild(row);
                    });
                    consoleEl.scrollTop = consoleEl.scrollHeight;
                } else {
                    consoleEl.innerHTML = '<div class="text-white-50 text-center py-4">Nenhum log operacional registrado hoje.</div>';
                }
            })
            .catch(() => {
                consoleEl.innerHTML = '<div class="text-danger text-center py-4">Falha ao carregar logs da rádio.</div>';
            });
    }

    function clearLogsView() {
        const consoleEl = document.getElementById('system-logs-console');
        if (consoleEl) {
            consoleEl.innerHTML = '<div class="text-white-50 text-center py-4">Visualização limpa. Clique em "Atualizar Logs" para recarregar.</div>';
        }
    }
