"    // Carregar Logs do Sistema
    function loadSystemLogs() {
        const consoleEl = document.getElementById('system-logs-console');
        if (!consoleEl) return;

        consoleEl.innerHTML = '<div class="text-white-50 text-center py-4"><span class="spinner-border spinner-border-sm me-2"></span> Carregando logs operacionais...</div>';

        fetch('/api/player/' + storeId + '/logs')
            .then(res => res.json())
            .then(data => {
                if (!data) return;
                consoleEl.innerHTML = '';
                if (Array.isArray(data) && data.length > 0) {
                    data.forEach(line => {
                        const row = document.createElement('div');
                        row.style.marginBottom = '2px';
                        let str = typeof line === 'string' ? line : (line.message || JSON.stringify(line));
                        let levelClass = 'log-line-info';
                        if (str.includes('[WARN') || str.includes('WARNING')) levelClass = 'log-line-warn';
                        if (str.includes('[ERR') || str.includes('ERROR') || str.includes('fail')) levelClass = 'log-line-err';

                        const safeMsg = str.replace(/</g, '&lt;').replace(/>/g, '&gt;');
                        row.innerHTML = `<span class="${levelClass}">${safeMsg}</span>`;
                        consoleEl.appendChild(row);
                    });
                    consoleEl.scrollTop = consoleEl.scrollHeight;
                } else {
                    consoleEl.innerHTML = '<div class="text-white-50 text-center py-4">Nenhum log operacional registrado hoje.</div>';
                }
            })
            .catch(() => {
                consoleEl.innerHTML = '<div class="text-danger text-center py-4">Falha ao carregar logs da rádio.</div>';
            });
    }"

