		artistDisplay = fmt.Sprintf("Aviso de Placa • Disparado por: %s", strings.TrimSpace(triggeredBy))
	}
	LogLocal("WARNING", "[Warning] Aviso de placa acionado: '%s' (Duração: %ds, Chime: %s, Operador: %s)", displayName, durationSecs, chimeFile, triggeredBy)

