157: func checkStoreAccess(session *models.SessionData, store *models.Store) error {
158: 	if session == nil {
159: 		return fmt.Errorf("não autenticado")
160: 	}
161: 
162: 	// 1. Administrador Master (TenantID == nil) tem acesso irrestrito a todas as rádios
163: 	if session.TenantID == nil {
164: 		return nil
165: 	}
166: 
167: 	// 2. Usuário de Empresa só pode acessar lojas da sua própria empresa
168: 	if store.TenantID != *session.TenantID {
169: 		return fmt.Errorf("você não tem permissão para acessar a rádio de outra empresa")
170: 	}
171: 
172: 	// 3. Usuário com loja específica vinculada só pode acessar a sua própria loja
173: 	if session.StoreID != nil && *session.StoreID != store.ID {
174: 		return fmt.Errorf("seu usuário tem permissão de acesso restrita apenas à sua própria filial")
175: 	}
176: 
177: 	return nil
178: }
