"func getCentralizedLogs(engineLogPath string, maxLines int) ([]string, error) {
	var entries []LogEntry

	// 1. Read player operational logs from SQLite database (works in both Windows and Docker Linux)
	if DB != nil {
		rows, err := DB.Query("SELECT timestamp, level, message FROM local_logs ORDER BY id DESC LIMIT 200")
		if err == nil {
			for rows.Next() {
				var ts, lvl, msg string
				if errScan := rows.Scan(&ts, &lvl, &msg); errScan == nil {
					entries = append(entries, LogEntry{
						Timestamp: ts,
						Source:    "PLAYER",
						Line:      fmt.Sprintf("[%s] %s", lvl, msg),
					})
				}
			}
			rows.Close()
		}
	}

	// 2. Read fallback local log file if exists
	playerLogPath := `c:\imc-audio-local\client_player.log`
	if runtime.GOOS != "windows" {
		playerLogPath = `/app/cache/client_player.log`
	}
	if len(entries) == 0 {
		playerLines, _ := tailFile(playerLogPath, 200)
		for _, l := range playerLines {
			if len(l) >= 21 && l[0] == '[' && l[20] == ']' {
				ts := l[1:20] // "2006-01-02 15:04:05"
				msg := l[22:]
				entries = append(entries, LogEntry{
					Timestamp: ts,
					Source:    "PLAYER",
					Line:      msg,
				})
			} else {
				entries = append(entries, LogEntry{
					Timestamp: time.Now().Format("2006-01-02 15:04:05"),
					Source:    "PLAYER",
					Line:      l,
				})
			}
		}
	}"

