"func SyncPlayHistoryToServer(cfg *Config) error {
	if DB == nil || cfg == nil || cfg.ServerURL == "" || cfg.StoreToken == "" {
		return nil
	}

	rows, err := DB.Query(`
		SELECT id, track_id, track_type, display_name, COALESCE(artist, ''), played_at, 
		       COALESCE(duration_seconds, 0), COALESCE(skipped_by_catchup, 0), COALESCE(style_name, ''), 
		       COALESCE(play_status, 'executada'), COALESCE(planned_block_time, ''), 
		       COALESCE(skip_reason, '')
		FROM play_history
		WHERE synced = 0
		ORDER BY played_at ASC
		LIMIT 200
	`)
	if err != nil {
		return fmt.Errorf("failed to query unsynced play history: %w", err)
	}
	defer rows.Close()

	type batchRecord struct {
		RowID            int64  `json:"-"`
		TrackID          string `json:"track_id"`
		TrackType        string `json:"track_type"`
		DisplayName      string `json:"display_name"`
		Artist           string `json:"artist"`
		PlayedAt         string `json:"played_at"`
		DurationSeconds  int    `json:"duration_seconds"`
		SkippedByCatchup int    `json:"skipped_by_catchup"`
		StyleName        string `json:"style_name"`
		PlayStatus       string `json:"play_status"`
		PlannedBlockTime string `json:"planned_block_time"`
		SkipReason       string `json:"skip_reason"`
	}

	var items []batchRecord
	for rows.Next() {
		var r batchRecord
		if err := rows.Scan(
			&r.RowID, &r.TrackID, &r.TrackType, &r.DisplayName, &r.Artist, &r.PlayedAt,
			&r.DurationSeconds, &r.SkippedByCatchup, &r.StyleName, &r.PlayStatus,
			&r.PlannedBlockTime, &r.SkipReason,
		); err == nil {
			items = append(items, r)
		} else {
			LogLocal("ERROR", "Scan error in SyncPlayHistoryToServer: %v", err)
		}
	}"

