"    function toggleSourceType(type) {
        const localWrapper = document.getElementById('local-media-wrapper');
        const streamWrapper = document.getElementById('stream-media-wrapper');
        const baseDirSelect = document.getElementById('base-directory');
        const streamUrlInput = document.getElementById('stream-url');

        if (type === 'STREAM') {
            if (localWrapper) localWrapper.classList.add('d-none');
            if (streamWrapper) streamWrapper.classList.remove('d-none');
            if (streamUrlInput) streamUrlInput.setAttribute('required', 'required');
            if (baseDirSelect) baseDirSelect.removeAttribute('required');
        } else {
            if (localWrapper) localWrapper.classList.remove('d-none');
            if (streamWrapper) streamWrapper.classList.add('d-none');
            if (streamUrlInput) streamUrlInput.removeAttribute('required');
        }
    }

    function applyStreamPreset(url) {
        const streamUrlInput = document.getElementById('stream-url');
        const nameInput = document.getElementById('name');
        const presetSelect = document.getElementById('stream-preset');

        if (url && url !== 'CUSTOM') {
            if (streamUrlInput) streamUrlInput.value = url;
            if (presetSelect && presetSelect.selectedIndex >= 0) {
                const selectedOpt = presetSelect.options[presetSelect.selectedIndex];
                const presetName = selectedOpt.getAttribute('data-name');
                if (presetName && nameInput && !nameInput.value) {
                    nameInput.value = presetName;
