	// 4. /blank_stream.mp3 endpoint - serves a continuous stream of silent MP3 frames for dormant input.http
	mux.HandleFunc("/blank_stream.mp3", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "audio/mpeg")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		// MPEG-1 Layer 3 44.1kHz 64kbps mono silent frame (208 bytes = 26ms audio)
		silentFrame := make([]byte, 208)
		silentFrame[0] = 0xFF
		silentFrame[1] = 0xFB
		silentFrame[2] = 0x50
		silentFrame[3] = 0xC0

		flusher, _ := w.(http.Flusher)
		ticker := time.NewTicker(26 * time.Millisecond)
		defer ticker.Stop()

		for {
			select {
			case <-r.Context().Done():
				return
			case <-ticker.C:
				if _, err := w.Write(silentFrame); err != nil {
					return
				}
				if flusher != nil {
					flusher.Flush()
				}
			}
		}
	})"

